/* DataHub — all page scripts, extracted from index.html for CSP compliance (script-src 'self'). Order preserved. */

/* mobile: bottom tab bar + menu sheet */
(function(){
  var bar=document.querySelector('.sitebar'), menu=document.getElementById('bn-menu');
  function setOpen(o){ bar.classList.toggle('nav-open',o); menu.setAttribute('aria-expanded',o); menu.classList.toggle('active',o); if(o) window.scrollTo({top:0,behavior:'smooth'}); }
  menu.addEventListener('click',function(){ setOpen(!bar.classList.contains('nav-open')); });
  document.addEventListener('click',function(e){
    if(e.target.closest('[data-nav],[data-theme-nav],.mega-col h4,[data-theme-page]')) setOpen(false);
  });
  function sync(){
    var a=document.querySelector('.view.active'), id=a?a.id.replace('view-',''):'';
    document.querySelectorAll('.bottom-nav [data-bn]').forEach(function(b){ b.classList.toggle('active', b.getAttribute('data-bn')===id); });
  }
  new MutationObserver(sync).observe(document.querySelector('main'),{subtree:true,attributes:true,attributeFilter:['class']});
  sync();
})();

;

  // ---- dropdown / popover toggling ----
  function closeAllNavItems(except){
    document.querySelectorAll('.nav-item.open').forEach(function(el){
      if(el !== except){ el.classList.remove('open'); el.querySelector('[aria-expanded]').setAttribute('aria-expanded','false'); }
    });
  }
  document.querySelectorAll('.nav-item').forEach(function(item){
    var trigger = item.querySelector('[aria-expanded]');
    trigger.addEventListener('click', function(e){
      e.stopPropagation();
      var willOpen = !item.classList.contains('open');
      closeAllNavItems(item);
      item.classList.toggle('open', willOpen);
      trigger.setAttribute('aria-expanded', String(willOpen));
    });
  });
  document.addEventListener('click', function(){ closeAllNavItems(null); });

  // ---- page switching (Home / Data & Insights) ----
  function showView(id, scrollToId){
    restoreThemeMoves();
    document.querySelectorAll('.view').forEach(function(v){ v.classList.remove('active'); });
    document.getElementById('view-' + id).classList.add('active');
    window.scrollTo({top:0, behavior:'instant'});
    if(id === 'dashboards'){
      requestAnimationFrame(function(){
        buildNSEChart('db-nse-inset', 'db-nse-svg', 'db-nse-tooltip');
        initPLFSMap('db-plfs-inset', 'db-plfs-svg');
      });
    }
    if(scrollToId){
      requestAnimationFrame(function(){
        var el = document.getElementById(scrollToId);
        if(el) el.scrollIntoView({behavior:'smooth', block:'start'});
      });
    }
  }

  // ---- theme pages (Employment / Entrepreneurship / Enabling Infrastructure) ----
  // These pages don't duplicate dashboard/insight markup — they borrow the real
  // nodes from Explore Dashboards + Data & Insights (so charts & accordions keep
  // working) and hand them back when the visitor navigates away.
  var activeThemePage = null;
  function restoreThemeMoves(){
    if(!activeThemePage) return;
    var k = activeThemePage;
    var tabPanel = document.getElementById('tab-' + k);
    var dashSlot = document.getElementById('theme-' + k + '-dash-slot');
    if(tabPanel && dashSlot){ Array.from(dashSlot.children).forEach(function(el){ tabPanel.appendChild(el); }); }
    var themeBody = document.querySelector('.theme-block[data-theme-key="' + k + '"] .theme-block-body');
    var insightsSlot = document.getElementById('theme-' + k + '-insights-slot');
    if(themeBody && insightsSlot){ Array.from(insightsSlot.children).forEach(function(el){ themeBody.appendChild(el); }); }
    activeThemePage = null;
  }
  function showThemeView(themeKey){
    if(activeThemePage === themeKey){
      document.querySelectorAll('.view').forEach(function(v){ v.classList.remove('active'); });
      document.getElementById('view-theme-' + themeKey).classList.add('active');
      window.scrollTo({top:0, behavior:'instant'});
      return;
    }
    restoreThemeMoves();
    document.querySelectorAll('.view').forEach(function(v){ v.classList.remove('active'); });
    var view = document.getElementById('view-theme-' + themeKey);
    if(!view) return;
    view.classList.add('active');

    var tabPanel = document.getElementById('tab-' + themeKey);
    var dashSlot = document.getElementById('theme-' + themeKey + '-dash-slot');
    if(tabPanel && dashSlot){ Array.from(tabPanel.children).forEach(function(el){ dashSlot.appendChild(el); }); }
    var themeBody = document.querySelector('.theme-block[data-theme-key="' + themeKey + '"] .theme-block-body');
    var insightsSlot = document.getElementById('theme-' + themeKey + '-insights-slot');
    if(themeBody && insightsSlot){ Array.from(themeBody.children).forEach(function(el){ insightsSlot.appendChild(el); }); }
    activeThemePage = themeKey;

    if(themeKey === 'employment'){
      requestAnimationFrame(function(){
        buildNSEChart('db-nse-inset', 'db-nse-svg', 'db-nse-tooltip');
        initPLFSMap('db-plfs-inset', 'db-plfs-svg');
      });
    }

    // reset the page's own segment control to "Dashboards"
    var tabs = Array.prototype.filter.call(view.querySelectorAll('.theme-segment-tabs .seg-tab'), function(b){ return !b.hidden; });
    var firstSeg = tabs.length ? tabs[0].getAttribute('data-segment') : 'dashboards';
    view.querySelectorAll('.theme-segment-tabs .seg-tab').forEach(function(b){ b.classList.toggle('active', b.getAttribute('data-segment') === firstSeg); });
    view.querySelectorAll('.theme-segment-panel').forEach(function(p){
      p.classList.toggle('active', p.getAttribute('data-segment') === firstSeg);
    });

    window.scrollTo({top:0, behavior:'instant'});
  }
  document.querySelectorAll('.theme-segment-tabs').forEach(function(tabRow){
    tabRow.querySelectorAll('.seg-tab').forEach(function(tabBtn){
      tabBtn.addEventListener('click', function(){
        var seg = tabBtn.getAttribute('data-segment');
        tabRow.querySelectorAll('.seg-tab').forEach(function(b){ b.classList.remove('active'); });
        tabBtn.classList.add('active');
        var view = tabRow.closest('.view');
        view.querySelectorAll('.theme-segment-panel').forEach(function(p){
          p.classList.toggle('active', p.getAttribute('data-segment') === seg);
        });
      });
    });
  });
  // "Browse by themes" mega-menu labels open the matching theme page
  document.querySelectorAll('.mega-col h4').forEach(function(h4){
    h4.style.cursor = 'pointer';
    h4.addEventListener('click', function(){
      var text = h4.textContent.trim().toLowerCase();
      var key = text === 'employment' ? 'employment' : text === 'entrepreneurship' ? 'entrepreneurship' : 'infrastructure';
      showThemeView(key);
      closeAllNavItems(null);
    });
  });
  // home-page quick links (Employment / Entrepreneurship / Enabling Infrastructure) open the theme page
  document.querySelectorAll('[data-theme-page]').forEach(function(pill){
    if(pill.classList.contains('theme-segment-tabs')) return;
    pill.addEventListener('click', function(e){
      e.preventDefault();
      showThemeView(pill.getAttribute('data-theme-page'));
    });
  });
  document.querySelectorAll('[data-nav]').forEach(function(btn){
    btn.addEventListener('click', function(){
      var target = btn.getAttribute('data-nav');
      if(target === 'home'){ showView('home'); }
      else if(target === 'insights'){ showView('insights'); }
      else if(target === 'dashboards'){ showView('dashboards'); }
    });
  });

  // ---- carousels ----
  document.querySelectorAll('[data-scroll]').forEach(function(btn){
    btn.addEventListener('click', function(){
      var parts = btn.getAttribute('data-scroll').split(':');
      var track = document.getElementById(parts[0] + '-track');
      var dir = parseInt(parts[1], 10);
      var step = track.clientWidth * 0.85;
      track.scrollBy({left: dir * step, behavior:'smooth'});
    });
  });

  // ---- Women's Employment Tracker (interactive, data-driven) ----
  var nseAvg = 18;
  var NSE_SHORT = {'Automobile & Auto Components':'Auto & Components','Fast Moving Consumer Goods':'FMCG','Financial Services & Insurance':'Financial Services','Oil, Gas & Consumable Fuels':'Oil & Gas','Information Technology':'IT'};
  var nseSectors = [
    ['Hospitals and Labs',49],['Textiles',37],['Consumer Services',36],['Information Technology',35],
    ['Banks',26],['Fast Moving Consumer Goods',20],['Financial Services & Insurance',18],['Services',16],
    ['Consumer Durables',15],['Media & Entertainment',15],['Automobile & Auto Components',14],['Pharma',13],
    ['Telecommunication',12],['Realty',11],['Diversified',8],['Oil, Gas & Consumable Fuels',7],
    ['Capital Goods',7],['Forest Materials',6],['Metals & Mining',6],['Chemicals',5],
    ['Other Utilities',5],['Power',5],['Construction Materials',3],['Construction',2]
  ].map(function(r){ return { label:r[0], pct:r[1] }; });

  function buildNSEChart(wrapId, svgId, tipId){
    wrapId = wrapId || 'dash-nse-inset'; svgId = svgId || 'dash-nse-svg'; tipId = tipId || 'dash-nse-tooltip';
    var wrap = document.getElementById(wrapId);
    var svgEl = document.getElementById(svgId);
    if (!wrap || !svgEl) return;
    var W = wrap.clientWidth ? wrap.clientWidth - 40 : 480;
    var rowH = 12, gap = 4, top = 18, axisH = 16;
    var labelW = Math.min(158, W * 0.36), barAreaX = labelW + 8, rightPad = 30;
    var barAreaW = W - barAreaX - rightPad, maxV = 60;
    var x = function(v){ return barAreaX + v / maxV * barAreaW; };
    var H = top + nseSectors.length * (rowH + gap) + axisH;
    svgEl.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
    svgEl.style.height = H + 'px';
    var F = 'font-family="Hind Siliguri, sans-serif"';
    var html = '', ax = x(nseAvg);
    [0,20,40,60].forEach(function(t){
      html += '<line x1="' + x(t) + '" y1="' + top + '" x2="' + x(t) + '" y2="' + (H - axisH) + '" stroke="var(--chart-grid)" stroke-width="0.8"/>';
      html += '<text x="' + x(t) + '" y="' + (H - 3) + '" text-anchor="middle" font-size="9.5" fill="var(--ink-faint)" ' + F + '>' + t + '%</text>';
    });
    nseSectors.forEach(function(d, i){
      var y = top + i * (rowH + gap), bw = d.pct / maxV * barAreaW;
      html += '<g class="nse-row" data-idx="' + i + '">';
      html += '<rect class="nse-hit" x="0" y="' + (y - gap / 2) + '" width="' + W + '" height="' + (rowH + gap) + '" fill="transparent"/>';
      var lab = (W < 520 && NSE_SHORT[d.label]) || d.label;
      html += '<text x="' + labelW + '" y="' + (y + rowH - 2) + '" text-anchor="end" font-size="10.5" fill="var(--ink-dim)" ' + F + '>' + lab.replace('&', '&amp;') + '</text>';
      html += '<rect class="nse-female" x="' + barAreaX + '" y="' + y + '" width="' + bw.toFixed(1) + '" height="' + rowH + '" rx="3" fill="var(--turmeric-500)"/>';
      html += '<text x="' + (barAreaX + bw + 4) + '" y="' + (y + rowH - 2) + '" font-size="10" font-weight="700" fill="var(--ink)" ' + F + '>' + d.pct + '%</text>';
      html += '</g>';
    });
    html += '<line x1="' + ax + '" y1="' + (top - 4) + '" x2="' + ax + '" y2="' + (H - axisH) + '" stroke="var(--indigo-900)" stroke-width="1.4" stroke-dasharray="4,3" pointer-events="none"/>';
    html += '<text x="' + (ax + 4) + '" y="' + (top - 7) + '" font-size="10" font-weight="700" fill="var(--indigo-900)" pointer-events="none" ' + F + '>All companies 18%</text>';
    svgEl.innerHTML = html;

    var tip = document.getElementById(tipId);
    svgEl.querySelectorAll('.nse-row').forEach(function(row){
      row.addEventListener('mousemove', function(e){
        var d = nseSectors[+row.getAttribute('data-idx')];
        tip.innerHTML = '<b>' + d.label.replace('&', '&amp;') + '</b><br>' + d.pct + '% women, FY 2025–26<br>All companies: 18%';
        var wrapRect = wrap.getBoundingClientRect();
        var left = e.clientX - wrapRect.left + 14, topPx = e.clientY - wrapRect.top + 12;
        if (left + 200 > wrap.clientWidth) left = e.clientX - wrapRect.left - 210;
        tip.style.left = left + 'px'; tip.style.top = topPx + 'px'; tip.style.opacity = '1';
        svgEl.querySelectorAll('.nse-row').forEach(function(r){ r.classList.toggle('dimmed', r !== row); });
      });
      row.addEventListener('mouseleave', function(){
        tip.style.opacity = '0';
        svgEl.querySelectorAll('.nse-row').forEach(function(r){ r.classList.remove('dimmed'); });
      });
    });
  }
  buildNSEChart();
  window.addEventListener('resize', function(){ buildNSEChart(); buildNSEChart('db-nse-inset', 'db-nse-svg', 'db-nse-tooltip'); });

