  /* ---- Employment insights: large listed enterprises / sector / KMP ---- */
  function wiEsc(t){ return String(t).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); }
  function wiLine(){
    var years=['2021–22','2022–23','2023–24','2024–25'];
    var series=[{name:'Women&#39;s representation overall',v:[20,19,18,18],c:'var(--l-all)',pos:'below'},{name:'Women employee representation',v:[22,23,22,23],c:'var(--l-emp)',pos:'above'},{name:'Women workers\' representation',v:[12,12,12,12],c:'var(--l-wrk)',pos:'below'}];
    var W=640,H=340,L=40,R=34,T=22,B=34,pw=W-L-R,ph=H-T-B,YM=30;
    function x(i){return L+pw*(i/(years.length-1))*0.94+pw*0.03;} function y(v){return T+(YM-v)/YM*ph;}
    var o='<svg class="lc" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Line chart of women&#39;s representation in large listed enterprises, 2021–22 to 2024–25">';
    [0,10,20,30].forEach(function(g){o+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(g)+'" y2="'+y(g)+'" stroke="var(--chart-grid)"/><text x="'+(L-8)+'" y="'+(y(g)+4)+'" text-anchor="end" font-size="12.5" fill="var(--ink-faint)">'+g+'%</text>';});
    years.forEach(function(t,i){o+='<text x="'+x(i)+'" y="'+(H-8)+'" text-anchor="middle" font-size="12.5" fill="var(--ink-faint)">'+t+'</text>';});
    series.forEach(function(s){
      o+='<polyline points="'+s.v.map(function(v,i){return x(i)+','+y(v);}).join(' ')+'" fill="none" stroke="'+s.c+'" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>';
      s.v.forEach(function(v,i){o+='<circle cx="'+x(i)+'" cy="'+y(v)+'" r="4.5" fill="'+s.c+'" stroke="var(--surface-sunken)" stroke-width="1.5"/><text x="'+x(i)+'" y="'+(s.pos==='above'?y(v)-12:y(v)+22)+'" text-anchor="middle" font-size="14" font-weight="700" fill="var(--ink)">'+v+'%</text>';});
    });
    var lg='<div class="legend">'+series.map(function(s){return '<span style="--c:'+s.c+'"><i></i>'+s.name+'</span>';}).join('')+'</div>';
    return '<p class="ctitle">Women&#39;s representation in large listed enterprises</p><p class="csub">Share of women in workforce (%) · 2021–22 to 2024–25</p>'+lg+o+'</svg><p class="key">Overall = all employees; employees = non-worker staff; workers = blue-collar level.</p>';
  }
  var WI_SECTORS=[['Hospitals & Labs',48],['Textiles',37],['Consumer Services',34],['Information Technology',34],['Banks',26],['Fast Moving Consumer Goods',21],['Financial Services',18],['Diversified',16],['Automobile and Auto Components',15],['Consumer Durables',14],['Media & Entertainment',14],['Services',14],['Telecommunication',12],['Pharma',12],['Realty',11],['Capital Goods (Industrial)',9],['Capital Goods',6],['Oil, Gas & Consumable Fuels',6],['Metals & Mining',6],['Forest Materials',5],['Chemicals',5],['Power',4],['Other Utilities',4],['Construction Materials',3],['Construction',2]];
  function wiSector(){
    var data=WI_SECTORS,OVERALL=18;
    function col(v){return v>25?'var(--b-hi)':(v<5?'var(--b-lo)':'var(--b-mid)');}
    var W=1000,H=470,L=40,R=10,T=28,B=150,YM=50,pw=W-L-R,ph=H-T-B,n=data.length,slot=pw/n,bw=slot*0.62;
    function y(v){return T+(YM-v)/YM*ph;}
    var o='<svg class="bc" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Column chart of women&#39;s representation by sector, ranked from 48% in hospitals and labs to 2% in construction">';
    [0,10,20,30,40,50].forEach(function(g){o+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(g)+'" y2="'+y(g)+'" stroke="var(--chart-grid)"/><text x="'+(L-8)+'" y="'+(y(g)+4)+'" text-anchor="end" font-size="12" fill="var(--ink-faint)">'+g+'%</text>';});
    data.forEach(function(d,i){var cx=L+slot*i+slot/2,top=y(d[1]);
      o+='<rect x="'+(cx-bw/2)+'" y="'+top+'" width="'+bw+'" height="'+(y(0)-top)+'" fill="'+col(d[1])+'" rx="2"/><text x="'+cx+'" y="'+(top-6)+'" text-anchor="middle" font-size="13" font-weight="700" fill="var(--ink)">'+d[1]+'%</text><text transform="translate('+(cx+4)+','+(y(0)+12)+') rotate(-45)" text-anchor="end" font-size="11.5" fill="var(--ink-dim)">'+wiEsc(d[0])+'</text>';});
    o+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(OVERALL)+'" y2="'+y(OVERALL)+'" stroke="var(--ref)" stroke-width="1.5" stroke-dasharray="6 4"/><text x="'+(W-R)+'" y="'+(y(OVERALL)-6)+'" text-anchor="end" font-size="12" font-weight="600" fill="var(--ink)">Overall: '+OVERALL+'%</text></svg>';
    return '<p class="ctitle">Women\'s representation by sector</p><p class="csub">Share of women in workforce (%) · ranked high to low · 2024–25</p><div class="legend sq"><span style="--c:var(--b-hi)"><i></i>Above 25%</span><span style="--c:var(--b-mid)"><i></i>5–25%</span><span style="--c:var(--b-lo)"><i></i>Below 5%</span><span><i class="dash"></i>Overall: 18%</span></div><div class="scroll">'+o+'</div><p class="key">Bars are coloured by band; the dashed line marks the overall women\'s share in large listed enterprises.</p>';
  }
  var WI_KMP=[['Hospitals & Labs',23,33],['Textiles',16,57],['Consumer Services',22,39],['Information Technology',20,45],['Banks',8,70],['Fast Moving Consumer Goods',16,53],['Financial Services',21,41],['Diversified',21,44],['Automobile and Auto Components',13,60],['Consumer Durables',20,47],['Media & Entertainment',18,46],['Services',24,36],['Telecommunication',16,56],['Pharma',19,49],['Realty',18,59],['Capital Goods (Industrial)',19,50],['Capital Goods',19,48],['Oil, Gas & Consumable Fuels',14,50],['Metals & Mining',12,61],['Forest Materials',11,68],['Chemicals',15,55],['Power',11,62],['Other Utilities',21,36],['Construction Materials',12,69],['Construction',21,48]];
  function wiKmpInit(host){
    var views={kmp:{i:1,max:30,color:'var(--bar-kmp)',label:'Women in KMP',title:'Women&#39;s share of key managerial positions',sub:'Share of KMP positions held by women (%) · by sector · FY 2024–25 · ranked high to low',ref:18,refLabel:'All sectors: 18%',key:'The dashed line marks the overall women&#39;s share of KMP positions (18%).'},
               none:{i:2,max:80,color:'var(--bar-none)',label:'Companies with no women in KMP',title:'Companies with no women in KMP',sub:'Share of companies with no woman in KMP (%) · by sector · FY 2024–25 · ranked high to low',ref:null,key:'Each bar is the percentage of companies in that sector with no woman in any KMP role.'}};
    var mode='kmp';
    function render(){var v=views[mode];
      var seg='<div class="seg" role="group" aria-label="Choose measure">'+Object.keys(views).map(function(k){return '<button type="button" data-m="'+k+'" aria-pressed="'+(k===mode)+'">'+views[k].label+'</button>';}).join('')+'</div>';
      var hdr='<div class="hdr"><span></span><div class="hl">'+(v.ref?'<span style="left:'+(v.ref/v.max*100)+'%">'+v.refLabel+'</span>':'')+'</div></div>';
      var rows=WI_KMP.slice().sort(function(a,b){return b[v.i]-a[v.i];}).map(function(d){var val=d[v.i],w=val/v.max*100;
        return '<div class="row"><div class="nm">'+wiEsc(d[0])+'</div><div class="trk">'+(v.ref?'<i class="ref" style="left:'+(v.ref/v.max*100)+'%"></i>':'')+'<div class="fill" style="width:'+w+'%;--c:'+v.color+'"></div><span class="lab" style="left:calc('+w+'% + 6px)">'+val+'%</span></div></div>';}).join('');
      host.innerHTML='<p class="ctitle">'+v.title+'</p><p class="csub">'+v.sub+'</p>'+seg+hdr+'<div class="rows">'+rows+'</div><p class="key">'+v.key+'</p>';}
    host.addEventListener('click',function(e){var b=e.target.closest('button[data-m]');if(!b)return;mode=b.getAttribute('data-m');render();});
    render();
  }
  INSIGHTS['insight-14']={title:"Women are 50% of college enrolments but just 18% of the large-enterprise workforce",byline:"Large listed enterprises · Women&#39;s representation, 2021–22 to 2024–25",chart:'<div class="wi" id="wi-host"></div>',initChart:function(){document.getElementById('wi-host').innerHTML=wiLine();},body:["Women's participation in higher education contrasts sharply with their representation in the listed-company workforce. They account for 50% of higher education enrolment but just 18% of the workforce in the covered companies. Their workforce share also declined from 20% in 2021–22 to 18% in 2024–25.", "The large listed enterprises of India are the top companies by market capitalisation and have the largest capacity to absorb workforce. Yet, 52% of these companies have less than 10% women. The representation of women at the worker (or blue-collar) level is even lower, at 12%, despite workers forming 41% of the listed workforce. Sectors such as Metals and Mining, Capital Goods, and Services, which employ a large share of workers, have yet to create a conducive environment for women to enter and participate in the workforce."]};
  INSIGHTS['insight-15']={title:"Women are concentrated in a few sectors, such as hospitals and textiles, and barely present in heavy manufacturing",byline:"Sector representation · Share of women in workforce, 2024–25",chart:'<div class="wi" id="wi-host"></div>',initChart:function(){document.getElementById('wi-host').innerHTML=wiSector();},body:["Women's representation across sectors remains highly uneven, with a handful of sectors driving the overall female workforce share of 18%. The distribution is highly skewed, with the top quintile of sectors reporting women's representation above 25%, while sectors in the bottom quintiles, particularly heavy industries, mining and construction, continue to have disproportionately low female participation. Meanwhile, sectors in the middle quintiles, such as FMCG and pharmaceuticals, are showing gradual improvements. For instance, women's representation in the pharmaceutical sector increased from 8% in FY 2020–21 to 12% in FY 2024–25, signalling progress, albeit from a low base.", "However, higher representation does not necessarily translate into equitable opportunities or career progression. Even in sectors with relatively high female participation, such as textiles, women remain concentrated in entry-level shopfloor roles, with limited representation in supervisory and managerial positions. Career progression therefore remains a significant challenge. Similarly, in retail, women tend to be concentrated in specific sub-sectors, such as beauty and apparel, while their representation remains limited in other segments, despite comparable job roles and working conditions. These patterns highlight that efforts should not stop at increasing women's representation. They should also address key barriers and enable progression into higher-skilled and leadership roles."]};
  

  /* ---- ASUSE insight (Entrepreneurship) ---- */
  function asuseInit(host){
    var MAX=60000,KEYS=['all','mfg','trade','oth'];
    var data={male:[['All sectors',53500,44500,9000],['Manufacturing',8400,6300,2100],['Trade',20700,17000,3700],['Other Services',24400,21200,3200]],
              female:[['All sectors',21400,20700,634.2],['Manufacturing',12900,12800,154.2],['Trade',3200,3100,138.4],['Other Services',5200,4800,341.5]]};
    var titles={male:'Men-owned enterprises',female:'Women-owned enterprises'};
    function fmt(k){return k>=1000?(k/1000).toFixed(1)+'M':k.toFixed(1)+'K';}
    function pct(a,b){return (a/b*100).toFixed(1)+'%';}
    function bar(v,tag,extra){var w=Math.min(Math.max(v/MAX*100,0),100),wc='max('+w+'%, 3px)',label='<b>'+fmt(v)+'</b> '+tag+(extra?' · '+extra:'');
      var lab=w>62?'<span class="lab in" style="right: calc(100% - '+w+'% + 8px)">'+label+'</span>':'<span class="lab" style="left: calc('+wc+' + 6px)">'+label+'</span>';
      return '<div class="brow"><div class="fill" style="width:'+wc+'"></div>'+lab+'</div>';}
    function grp(r,i){var k=KEYS[i%4];return '<div class="grp" style="--c: var(--c-'+k+'); --on: var(--on-'+k+')"><div class="gname">'+r[0]+' <span>· '+fmt(r[1])+'</span></div>'+bar(r[2],'OAE','')+bar(r[3],'HWE',pct(r[3],r[1]))+'</div>';}
    var html='<div class="panels">';
    ['male','female'].forEach(function(side){var rows=data[side],gl='',ax='',t;
      for(t=0;t<=3;t++)gl+='<i class="gl" style="left:'+(t/3*100)+'%"></i>';
      for(t=0;t<=3;t++)ax+='<span style="left:'+(t/3*100)+'%">'+(t===0?'0':fmt(MAX*t/3).replace('.0M','M'))+'</span>';
      html+='<div class="panel"><h4>'+titles[side]+'</h4><p class="psub">'+fmt(rows[0][1])+' in all · by sector · ASUSE 2025</p><div class="plot">'+gl+rows.map(grp).join('')+'</div><div class="axis">'+ax+'</div></div>';});
    html+='</div><p class="key"><span>Both charts use the same scale. Bars under 1% of the scale are drawn at a minimum width.</span><span><b>OAE</b> <span>own-account, no hired worker</span></span><span><b>HWE</b> <span>hires at least one worker</span> · % = share of that group</span></p>';
    host.innerHTML=html;
  }
  INSIGHTS['insight-17']={title:"Women own 21.4 million enterprises. Only 0.6 million hire workers.",byline:"ASUSE 2025 · Enterprises by owner's sex and sector",chart:'<div class="as" id="as-host"></div>',initChart:function(){asuseInit(document.getElementById('as-host'));},body:["Across manufacturing, trade and other services, men own 53.5 million proprietary enterprises and women own 21.4 million, or 29% of the total 74.9 million. Only 3.0% of women-owned enterprises have hired workers (hired-worker establishments, or HWEs, in ASUSE terms), compared with 16.8% of men-owned enterprises.", "Manufacturing is the only sector where women own more enterprises than men: 12.9 million compared with 8.4 million. Yet only 1.2% (154 thousand) of women-owned manufacturing enterprises have hired workers, compared with 25% (2.1 million) of men-owned enterprises. This is the widest gap in hiring rates across the three sectors.", "In trade, men own more than six times as many enterprises as women. In other services, men own nearly five times as many enterprises.", "<b>Udaiti's Take —</b> Most women-owned enterprises remain micro or subsistence-driven, with only about 3% hiring workers, compared with 16.8% of men-owned enterprises. Many of these enterprises may be necessity-driven, reflecting limited wage employment opportunities, household income shocks and reliance on home-based work. Within this overall base of women-owned enterprises, growth-oriented female-owned enterprises (GoFEs) — enterprises with an established scale of operations, ambition and potential to grow — remain underserved due to gender inequities in access to finance, markets and growth support. Addressing these barriers can enable GoFEs to scale, driving greater investment, productivity and employment, particularly for women."]};

  /* ---- NEW — Insight 07: women in regular-wage work without a written contract (PLFS 2025) ---- */
var I7_RESIZE_BOUND = false, I7_CURRENT = function(){ return 's7-a'; };

var I7_SECTORS = [
  { label:'Household domestic services', value:4.43 },
  { label:'Education',                   value:3.42 },
  { label:'Manufacturing',               value:2.67, mfg:true },
  { label:'Wholesale & retail trade',    value:1.82 },
  { label:'Human health & social work',  value:1.69 }
];
var I7_MFG_TOTAL = 2.67; // million
var I7_SUBS = [
  { label:'Apparel',      value:559341, col:'var(--indigo-900)' },
  { label:'Textiles',             value:373492, col:'var(--indigo-700)' },
  { label:'Food products',        value:367919, col:'var(--indigo-500)' },
  { label:'Other manufacturing',  value:149633, col:'var(--turmeric-500)', dark:true },
  { label:'Chemicals & products', value:137004, col:'color-mix(in srgb,#ffd400 45%,#fff)', dark:true }
];

function buildViz7(step){
  var body = document.getElementById('viz-insight-7-body');
  if (!body) return;
  var W = Math.max(body.clientWidth || 560, 300);
  var svg = '';
  if (step === 's7-a' || step === 's7-b'){
    var labW = Math.min(192, W * 0.4), valW = 44, rowH = 40, barH = 18, max = 4.43;
    var H = I7_SECTORS.length * rowH + 4;
    svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" style="height:' + H + 'px">';
    I7_SECTORS.forEach(function(d, i){
      var y = i * rowH + 4, hl = step === 's7-b' && d.mfg, dim = step === 's7-b' && !d.mfg;
      var bw = (W - labW - valW - 8) * d.value / max;
      if (hl) svg += '<rect x="0" y="' + (y - 4) + '" width="' + W + '" height="' + (rowH - 2) + '" rx="6" fill="var(--accent-wash)" stroke="var(--accent)" stroke-width="1.2"/>';
      svg += '<text x="8" y="' + (y + barH / 2 + 4) + '" font-size="11" fill="' + (hl ? 'var(--accent-ink)' : 'var(--ink)') + '" font-weight="' + (hl ? 700 : 400) + '" opacity="' + (dim ? .3 : 1) + '">' + d.label.replace('&', '&amp;') + '</text>';
      svg += '<rect x="' + labW + '" y="' + y + '" width="' + (W - labW - valW - 8) + '" height="' + barH + '" rx="3" fill="var(--khadi-200)" opacity="' + (dim ? .5 : 1) + '"/>';
      svg += '<rect x="' + labW + '" y="' + y + '" width="' + bw.toFixed(1) + '" height="' + barH + '" rx="3" fill="' + (hl ? 'var(--turmeric-500)' : 'var(--chart-line)') + '" opacity="' + (dim ? .25 : 1) + '"/>';
      svg += '<text x="' + (W - valW + 2) + '" y="' + (y + barH / 2 + 4) + '" font-size="11" style="font-variant-numeric:tabular-nums" fill="var(--ink-dim)" opacity="' + (dim ? .35 : 1) + '">' + d.value.toFixed(2) + 'M</text>';
    });
    svg += '</svg>';
  } else if (step === 's7-c'){
    var top3 = I7_SUBS.slice(0, 3), top3Sum = top3.reduce(function(s, d){ return s + d.value; }, 0) / 1e6;
    var rest = I7_MFG_TOTAL - top3Sum, x0 = 0, bw = W, barY = 70, barH = 46, H = 250;
    svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" style="height:' + H + 'px">';
    var bx = x0 + bw * top3Sum / I7_MFG_TOTAL;
    svg += '<path d="M1 ' + (barY - 12) + 'V' + (barY - 22) + 'H' + (bx - 1) + 'V' + (barY - 12) + '" fill="none" stroke="var(--ink)" stroke-width="1.3"/>';
    svg += '<text x="1" y="' + (barY - 30) + '" font-size="12.5" font-weight="700" fill="var(--ink)">' + top3Sum.toFixed(2) + 'M · ' + Math.round(top3Sum / I7_MFG_TOTAL * 100) + '% of manufacturing</text>';
    var x = x0;
    top3.forEach(function(d){
      var w = bw * (d.value / 1e6) / I7_MFG_TOTAL;
      svg += '<rect x="' + x.toFixed(1) + '" y="' + barY + '" width="' + (w - 2).toFixed(1) + '" height="' + barH + '" rx="3" fill="' + d.col + '"/>';
      svg += '<text x="' + (x + 8).toFixed(1) + '" y="' + (barY + 28) + '" font-size="11.5" font-weight="700" fill="#fff" style="font-variant-numeric:tabular-nums">' + Math.round(d.value / 1000) + 'K</text>';
      x += w;
    });
    svg += '<rect x="' + x.toFixed(1) + '" y="' + barY + '" width="' + (x0 + bw - x).toFixed(1) + '" height="' + barH + '" rx="3" fill="var(--khadi-300)"/>';
    svg += '<text x="' + (x + 8).toFixed(1) + '" y="' + (barY + 28) + '" font-size="11.5" font-weight="600" fill="var(--ink-dim)" style="font-variant-numeric:tabular-nums">' + rest.toFixed(2) + 'M</text>';
    var ly = barY + barH + 30;
    top3.concat([{ label:'All other manufacturing sub-sectors', col:'var(--khadi-300)', value: rest * 1e6 }]).forEach(function(d, i){
      var yy = ly + i * 24;
      svg += '<rect x="1" y="' + (yy - 10) + '" width="12" height="12" rx="2" fill="' + d.col + '"/>';
      svg += '<text x="20" y="' + yy + '" font-size="11.5" fill="var(--ink)">' + d.label + '</text>';
      svg += '<text x="' + (W - 2) + '" y="' + yy + '" text-anchor="end" font-size="11" style="font-variant-numeric:tabular-nums" fill="var(--ink-dim)">' + (d.value >= 1e6 ? (d.value / 1e6).toFixed(2) + 'M' : Math.round(d.value / 1000) + 'K') + '</text>';
    });
    svg += '</svg>';
  } else {
    // bubbles: area ∝ value, laid out left to right along a gentle wave
    var H = 300, maxR = Math.min(76, W / 7.6), maxV = I7_SUBS[0].value, gap = 6;
    var rs = I7_SUBS.map(function(d){ return maxR * Math.sqrt(d.value / maxV); });
    var total = rs.reduce(function(s, r){ return s + 2 * r; }, 0) + gap * (rs.length - 1);
    var scale = total > W ? W / total : 1;
    rs = rs.map(function(r){ return r * scale; });
    total = Math.min(total * scale, W);
    var cx = (W - total) / 2;
    svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" style="height:' + H + 'px">';
    I7_SUBS.forEach(function(d, i){
      var r = rs[i]; cx += r;
      var cy = H / 2 + (i % 2 ? 1 : -1) * Math.min(28, 90 - r * .6) * (i ? 1 : 0);
      var fs = r > 50 ? 11.5 : r > 36 ? 10 : 8.5, txt = d.dark ? 'var(--accent-ink)' : '#fff';
      var words = d.label.split(' '), lines = [], cur = '', maxC = Math.floor(r * 1.6 / (fs * .56));
      words.forEach(function(w){ var t = cur ? cur + ' ' + w : w; if (t.length <= maxC) cur = t; else { if (cur) lines.push(cur); cur = w; } });
      if (cur) lines.push(cur); lines = lines.slice(0, 2);
      var lh = fs * 1.2, y0 = cy - (lines.length * lh) / 2 + fs * .2;
      svg += '<g class="bub"><title>' + d.label.replace('&', '&amp;') + ': ' + d.value.toLocaleString('en-IN') + ' women workers without written contracts</title>';
      svg += '<circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="' + r.toFixed(1) + '" fill="' + d.col + '"/>';
      lines.forEach(function(l, li){ svg += '<text x="' + cx.toFixed(1) + '" y="' + (y0 + li * lh).toFixed(1) + '" text-anchor="middle" font-size="' + fs + '" font-weight="600" fill="' + txt + '">' + l.replace('&', '&amp;') + '</text>'; });
      svg += '<text x="' + cx.toFixed(1) + '" y="' + (y0 + lines.length * lh + 3).toFixed(1) + '" text-anchor="middle" font-size="' + (fs - .5) + '" style="font-variant-numeric:tabular-nums" fill="' + txt + '" opacity=".9">' + Math.round(d.value / 1000) + 'K</text></g>';
      cx += r + gap;
    });
    svg += '</svg>';
  }
  body.innerHTML = svg;
}

function activateStep7(stepId){
  var key = (stepId === 's7-c') ? 'c' : (stepId === 's7-d') ? 'd' : 'ab';
  document.querySelectorAll('#steps-insight-7 ~ .scrolly-viz .viz-title-alt, .viz-card .viz-title-alt').forEach(function(el){ el.hidden = el.getAttribute('data-for') !== key; });
  buildViz7(stepId);
}

// root = the scrolling element (index.html: modalBody). observers = array to push into (index.html: activeObservers).
function initInsight07(root, observers){
  activateStep7('s7-a');
  var steps = document.querySelectorAll('#steps-insight-7 .step'), current = 's7-a';
  var obs = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if (entry.isIntersecting && entry.intersectionRatio >= 0.5) {
        steps.forEach(function(s){ s.classList.toggle('active', s === entry.target); });
        current = entry.target.getAttribute('data-step');
        activateStep7(current);
      }
    });
  }, { root: root, threshold: 0.5, rootMargin: '-10% 0px -10% 0px' });
  steps.forEach(function(s){ obs.observe(s); });
  if (observers) observers.push(obs);
  I7_CURRENT = function(){ return current; };
  if (!I7_RESIZE_BOUND){ I7_RESIZE_BOUND = true; window.addEventListener('resize', function(){ if (document.getElementById('viz-insight-7-body')) buildViz7(I7_CURRENT()); }); }
}

  INSIGHTS['insight-no-contract']={title:'57% of women in regular-wage jobs have no written contract, 2.67 million of them in manufacturing',byline:'PLFS 2025 · Women in regular-wage work without written contracts, by sector',scrolly:true,chart:'<div class="modal-scrolly"><div class="scrolly-steps" id="steps-insight-7"><div class="step active" data-step="s7-a"><div class="step-inner"><span class="step-num">1</span><div class="step-tag">Sectors overview</div><h4>Five sectors account for the majority of women in regular-wage work without written contracts</h4><p>Among women in regular-wage employment, 4.43 million in household domestic services have no written job contract. Education follows at 3.42 million, then manufacturing at 2.67 million.</p></div></div><div class="step" data-step="s7-b"><div class="step-inner"><span class="step-num">2</span><div class="step-tag">The actionable sector</div><h4>In manufacturing, 2.67 million women have no written job contract.</h4><p>Unlike domestic work or education, manufacturing has factory inspectors, export compliance audits, and global buyers — three pressure points that don\'t exist elsewhere.</p></div></div><div class="step" data-step="s7-c"><div class="step-inner"><span class="step-num">3</span><div class="step-tag">Three sub-sectors stand out</div><h4>Apparel, textiles and food manufacturing account for 1.3 million women without written job contracts.</h4><p>These are export-facing sectors. The brands buying from Indian factories already have supplier codes of conduct. <b>Contract verification could be built into audit requirements today.</b></p></div></div><div class="step" data-step="s7-d"><div class="step-inner"><span class="step-num">4</span><div class="step-tag">Scale by sub-sector</div><h4>Each bubble is a sub-sector. Size tells you the scale of the problem.</h4><p>Textiles accounts for 373,000 women without written job contracts, while food manufacturing accounts for 368,000. Larger bubbles represent higher numbers of women.</p></div></div></div><div class="scrolly-viz"><div class="viz-sticky"><div class="viz-card"><div class="viz-card-title"><span class="viz-title-alt" data-for="ab">Women Without Written Contracts by Sector</span><span class="viz-title-alt" data-for="c" hidden>Inside Manufacturing · 2.67M Women Without Written Contracts</span><span class="viz-title-alt" data-for="d" hidden>Manufacturing Sub-sectors</span></div><div class="viz-card-sub"><span class="viz-title-alt" data-for="ab">Women in regular-wage employment, in millions: PLFS 2025</span><span class="viz-title-alt" data-for="c" hidden>Top three sub-sectors vs. the rest of manufacturing · PLFS 2025</span><span class="viz-title-alt" data-for="d" hidden>Women in regular-wage employment- Larger bubbles represent more women · PLFS 2025</span></div><div id="viz-insight-7-body"></div></div></div></div></div>',initChart:function(){ initInsight07(modalBody, activeObservers); },body:['A written contract is the legal basis for EPF, maternity benefit, minimum wage enforcement, and grievance redressal. Without it, employment is informal in practice regardless of how it is classified. Manufacturing alone has 2.67 million women workers without written contracts, concentrated in apparel, textiles, and food.','Household domestic services has the highest number of women in regular-wage employment without written job contracts, at 4.43 million. Education follows with 3.42 million, then manufacturing with 2.67 million, wholesale and retail trade with 1.82 million, and human health and social work with 1.69 million. Within manufacturing, apparel accounts for 559K women without written job contracts, textiles for 373K and food manufacturing for 368K. Together, these sub-sectors account for about 1.3 million women — nearly half the sector\'s total in regular-wage manufacturing jobs without written contracts.','<b>Udaiti\'s Take —</b> The absence of a written contract is the most concrete and measurable form of labour market exclusion. It is also the most tractable: a contract is binary, it either exists or it does not. States need to build mechanisms, aligned with the new labour codes, to ensure all workers have written contracts.']};

