  scrim.addEventListener('click', function(e){ if (e.target === scrim) { scrim.classList.remove('open'); teardownObservers(); } });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') { scrim.classList.remove('open'); teardownObservers(); } });

