/* carousel pagination dots (mobile-first pattern) + back to top */
(function(){
  document.querySelectorAll('.carousel').forEach(function(car){
    var track=car.querySelector('.carousel-track'); if(!track) return;
    var items=[].slice.call(track.children).filter(function(e){return e.offsetParent!==null||true;});
    if(items.length<2) return;
    var dots=document.createElement('div'); dots.className='carousel-dots'; dots.setAttribute('role','tablist');
    items.forEach(function(it,i){var b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Go to item '+(i+1));b.addEventListener('click',function(){track.scrollTo({left:it.offsetLeft-track.offsetLeft-parseFloat(getComputedStyle(track).paddingLeft||0),behavior:'smooth'});});dots.appendChild(b);});
    car.appendChild(dots);
    function sync(){var x=track.scrollLeft+track.clientWidth/2-parseFloat(getComputedStyle(track).paddingLeft||0);var best=0,bd=1e9;items.forEach(function(it,i){var c=it.offsetLeft-track.offsetLeft+it.offsetWidth/2;var d=Math.abs(c-x);if(d<bd){bd=d;best=i;}});[].forEach.call(dots.children,function(d,i){d.classList.toggle('on',i===best);d.setAttribute('aria-selected',i===best);});}
    track.addEventListener('scroll',function(){window.requestAnimationFrame(sync);},{passive:true}); window.addEventListener('resize',sync); sync();
  });
  document.addEventListener('click',function(e){var b=e.target.closest('.to-top'); if(b) window.scrollTo({top:0,behavior:'smooth'});});
})();

