/* hero: live network graph — real DataHub figures as labelled hubs.
   Pauses off screen; shows the finished frame when reduced motion is on. */
(function(){
  var hero=document.querySelector('.hero-video'), art=document.getElementById('hero-net'), cv=document.getElementById('hero-net-cv');
  if(!hero||!art||!cv) return;
  var REDUCED=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var HUBS=[
    {v:'40.0%', k:'female LFPR, PLFS 2025'},
    {v:'18%',   k:'of key managerial roles held by women, FY 2024–25'},
    {v:'11.7%', k:'women in NSE-listed firms'},
    {v:'21.4M', k:'women-owned enterprises, ASUSE 2025'},
    {v:'3%',    k:'of women-owned firms hire workers'},
    {v:'57%',   k:'regular-wage women with no written contract'}
  ];
  var S, nodes=[], raf=null, t0=null, mx=0, my=0, tx=0, ty=0, running=false;
  function hash(i){ var x=Math.sin(i*127.1+311.7)*43758.5453; return x-Math.floor(x); }
  function ease(t){ return t<0?0:t>1?1:1-Math.pow(1-t,3); }
  function size(){ var r=cv.getBoundingClientRect(), d=Math.min(window.devicePixelRatio||1,2);
    cv.width=Math.round(r.width*d); cv.height=Math.round(r.height*d); var ctx=cv.getContext('2d'); ctx.setTransform(d,0,0,d,0,0); return {ctx:ctx,w:r.width,h:r.height}; }
  function build(){
    S=size(); nodes=[];
    var n=Math.round(Math.max(36,Math.min(80,S.w*S.h/4200)));
    for(var i=0;i<n;i++) nodes.push({x:.06+hash(i+1)*.9, y:.08+hash(i+101)*.84, ph:hash(i+7)*6.28, sp:.15+hash(i+9)*.25, hub:-1, d:hash(i+3)*1.2});
    var narrow=S.w<560, spots=narrow?[[.08,.16],[.08,.5],null,[.08,.84]]:[[.30,.20],[.62,.12],[.84,.34],[.56,.50],[.26,.66],[.50,.86]], k=0;
    HUBS.forEach(function(h,j){ if(!spots[j]) return; nodes.push({x:spots[j][0], y:spots[j][1], ph:j, sp:.12, hub:j, d:1.4+(k++)*.35}); });
  }
  function pos(nd,t){ var a=REDUCED?0:t*nd.sp+nd.ph, f=nd.hub>=0?.6:1; return [(nd.x+Math.sin(a)*.012)*S.w+tx*f, (nd.y+Math.cos(a*.9)*.018)*S.h+ty*f]; }
  function frame(now){
    if(t0===null) t0=now; var t=REDUCED?99:(now-t0)/1000, ctx=S.ctx;
    tx+=(mx-tx)*.06; ty+=(my-ty)*.06;
    ctx.clearRect(0,0,S.w,S.h);
    var P=nodes.map(function(nd){ return pos(nd,t); }), lim=Math.min(S.w,S.h)*.32;
    ctx.lineWidth=1;
    for(var i=0;i<nodes.length;i++) for(var j=i+1;j<nodes.length;j++){
      var dx=P[i][0]-P[j][0], dy=P[i][1]-P[j][1], dd=Math.sqrt(dx*dx+dy*dy); if(dd>lim) continue;
      var g=ease((t-Math.max(nodes[i].d,nodes[j].d)-.3)/.9); if(g<=0) continue;
      var hubE=nodes[i].hub>=0||nodes[j].hub>=0;
      ctx.strokeStyle=hubE?'rgba(0,159,162,'+(.42*(1-dd/lim))+')':'rgba(27,103,117,'+(.22*(1-dd/lim))+')';
      ctx.beginPath(); ctx.moveTo(P[i][0],P[i][1]); ctx.lineTo(P[i][0]-dx*g,P[i][1]-dy*g); ctx.stroke();
    }
    ctx.textBaseline='middle';
    nodes.forEach(function(nd,i){
      var a=ease((t-nd.d)/.6); if(a<=0) return; var x=P[i][0], y=P[i][1];
      ctx.globalAlpha=a;
      if(nd.hub<0){ ctx.fillStyle='#56C5D0'; ctx.beginPath(); ctx.arc(x,y,2.6,0,6.2832); ctx.fill(); return; }
      var h=HUBS[nd.hub], la=ease((t-nd.d-.4)/.6);
      ctx.fillStyle='rgba(255,212,0,.28)'; ctx.beginPath(); ctx.arc(x,y,11+Math.sin(t*1.6+nd.hub)*1.5,0,6.2832); ctx.fill();
      ctx.fillStyle='#1b6775'; ctx.beginPath(); ctx.arc(x,y,5.5,0,6.2832); ctx.fill();
      if(la<=0) return;
      ctx.globalAlpha=la;
      ctx.font='700 17px "Hind Siliguri", sans-serif'; var w1=ctx.measureText(h.v).width;
      ctx.font='400 12.5px "Hind Siliguri", sans-serif'; var w2=ctx.measureText(h.k).width;
      var bw=Math.max(w1,w2)+22, bh=44, bx=Math.min(x+14,S.w-bw-4), by=y-bh/2;
      if(bx<x&&bx+bw>x-14) bx=x-bw-14; bx=Math.max(4,bx);
      ctx.fillStyle='#fff'; ctx.strokeStyle='rgba(35,31,32,.1)';
      ctx.beginPath(); if(ctx.roundRect) ctx.roundRect(bx,by,bw,bh,9); else ctx.rect(bx,by,bw,bh); ctx.fill(); ctx.stroke();
      ctx.fillStyle='#231f20'; ctx.font='700 17px "Hind Siliguri", sans-serif'; ctx.fillText(h.v,bx+11,by+16);
      ctx.fillStyle='rgba(35,31,32,.72)'; ctx.font='400 12.5px "Hind Siliguri", sans-serif'; ctx.fillText(h.k,bx+11,by+32);
    });
    ctx.globalAlpha=1;
    if(!REDUCED&&running) raf=requestAnimationFrame(frame);
  }
  function start(){ if(running) return; if(!S||S.w<2||Math.abs(cv.getBoundingClientRect().width-S.w)>1) build(); running=true; raf=requestAnimationFrame(frame); }
  function stop(){ running=false; cancelAnimationFrame(raf); }
  build();
  var fontsReady=(document.fonts&&document.fonts.ready)||Promise.resolve();
  if(REDUCED){ fontsReady.then(function(){ frame(0); }); }
  else{
    // only animate while the hero is on screen, the Home view is showing and the tab is visible
    var vis=false;
    function sync(){ (vis&&!document.hidden&&hero.offsetParent!==null)?start():stop(); }
    new IntersectionObserver(function(es){ vis=es[0].isIntersecting; sync(); },{threshold:.05}).observe(hero);
    document.addEventListener('visibilitychange',sync);
    new MutationObserver(sync).observe(document.getElementById('view-home'),{attributes:true,attributeFilter:['class']});
  }
  hero.addEventListener('pointermove',function(e){ var b=hero.getBoundingClientRect(); mx=((e.clientX-b.left)/b.width-.5)*-22; my=((e.clientY-b.top)/b.height-.5)*-14; });
  hero.addEventListener('pointerleave',function(){ mx=0; my=0; });
  var rt; window.addEventListener('resize',function(){ clearTimeout(rt); rt=setTimeout(function(){ build(); if(REDUCED) frame(0); },150); });
})();

;

