/* ---- DataHub search: header box submits to a dedicated results page (#search=…) ---- */
(function(){
  var navForm = document.getElementById('nav-search-form');
  var navInput = navForm ? navForm.querySelector('input') : null;
  var view = document.getElementById('view-search');
  if(!navForm || !navInput || !view) return;
  var srForm = document.getElementById('sr-form'), srInput = document.getElementById('sr-input');
  var srTitle = document.getElementById('sr-title'), srSub = document.getElementById('sr-sub');
  var srFilters = document.getElementById('sr-filters'), srList = document.getElementById('sr-results');
  var THEME_NAMES = { employment:'Employment', entrepreneurship:'Entrepreneurship', infrastructure:'Enabling Infrastructure' };
  var TYPES = ['Dashboards','Insights','Themes'];
  var SUGGEST = ['PLFS','EPFO','BRSR','Key management','Pay gap','Startup policy','Self-employment','Bus travel'];
  var state = { q:'', filter:'All', results:[], prev:null };

  function txt(el){ return el ? el.textContent.replace(/\s+/g,' ').trim() : ''; }
  function strip(h){ var d=document.createElement('div'); d.innerHTML=h||''; return d.textContent.replace(/\s+/g,' ').trim(); }
  function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); }
  function norm(s){ return ' '+String(s).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9%₹.]+/g,' ')+' '; }
  function has(h,t){ return h.indexOf(' '+t)>=0; }
  function insightsObj(){ try{ return INSIGHTS; }catch(e){ return {}; } }

  function buildIndex(){
    var idx=[], seen={}, INS=insightsObj();
    document.querySelectorAll('.insight-card.listing[data-modal]').forEach(function(c){
      var k=c.getAttribute('data-modal'); if(seen[k]) return; seen[k]=1;
      var d=INS[k]||{}, blk=c.closest('[data-theme-key]'), sub=c.closest('.theme-subgroup');
      var subName = sub ? txt(sub.querySelector('.theme-subgroup-head')).replace(/\d+$/,'').trim() : '';
      var svg=c.querySelector('.insight-inset svg');
      idx.push({type:'Insights', key:k, title:txt(c.querySelector('h3'))||strip(d.title), sum:txt(c.querySelector('.insight-text p')),
        meta:[blk?THEME_NAMES[blk.getAttribute('data-theme-key')]:'', subName].filter(Boolean).join(' · '),
        source:txt(c.querySelector('.insight-date')), thumb: svg ? svg.outerHTML : '',
        body:[strip(d.title), strip(d.byline), (d.body||[]).map(strip).join(' ')].join(' ')});
    });
    document.querySelectorAll('.db-tab-panel').forEach(function(p){
      if(p.hidden) return;
      var tab=p.id.replace('tab-','');
      p.querySelectorAll('.dbcard').forEach(function(card,i){
        if(card.hidden) return;
        if(!card.id) card.id='dbcard-'+tab+'-'+i;
        var link=card.querySelector('.dbcard-main a.btn[href^="http"]');
        idx.push({type:'Dashboards', tab:tab, id:card.id, title:txt(card.querySelector('.dbcard-head h3')), sum:txt(card.querySelector('.dbcard-head-main p')),
          meta:THEME_NAMES[tab]||'', href: link ? link.getAttribute('href') : '',
          body:[txt(card.querySelector('.dash-caption'))].concat([].map.call(card.querySelectorAll('.mini-insight'), txt)).join(' ')});
      });
    });
    Object.keys(THEME_NAMES).forEach(function(k){
      var v=document.getElementById('view-theme-'+k); if(!v) return;
      idx.push({type:'Themes', theme:k, title:THEME_NAMES[k], sum:txt(v.querySelector('.db-header p')), meta:'Theme page', body:''});
    });
    return idx;
  }
  function run(q){
    var terms=norm(q).trim().split(/\s+/).filter(Boolean), nq=norm(q).trim();
    if(!terms.length) return [];
    var O={Dashboards:0,Insights:1,Themes:2};
    return buildIndex().map(function(r){
      var T=norm(r.title), S=norm(r.sum+' '+r.meta+' '+(r.source||'')), B=norm(r.body), score=0;
      for(var i=0;i<terms.length;i++){
        var t=terms[i], hit=has(T,t)?6:has(S,t)?3:has(B,t)?1:0;
        if(!hit) return null; score+=hit;
      }
      if(T.indexOf(nq)>=0) score+=5;
      return {r:r,score:score};
    }).filter(Boolean).sort(function(a,b){ return (O[a.r.type]-O[b.r.type])||(b.score-a.score); }).map(function(x){ return x.r; });
  }
  function hl(s, terms){
    var out=esc(s);
    terms.forEach(function(t){ if(t.length<2) return; out=out.replace(new RegExp('(?<![A-Za-z0-9])('+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'),'<mark>$1</mark>'); });
    return out;
  }
  function snippet(r, terms){
    var src=r.sum, n=norm(src);
    if(!terms.some(function(t){ return has(n,t); }) && r.body){
      var nb=r.body.toLowerCase(), pos=-1;
      terms.some(function(t){ pos=nb.search(new RegExp('(^|[^a-z0-9])'+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'))); return pos>=0; });
      if(pos>=0){ var a=Math.max(0,pos-80); src=(a>0?'…':'')+r.body.slice(a,pos+160)+'…'; }
    }
    if(src.length>230) src=src.slice(0,227)+'…';
    return src;
  }
  var ICON = {
    Dashboards:'<svg class="icon" viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="9" rx="1.5"/><rect x="14" y="3" width="7" height="5" rx="1.5"/><rect x="14" y="12" width="7" height="9" rx="1.5"/><rect x="3" y="16" width="7" height="5" rx="1.5"/></svg>',
    Themes:'<svg class="icon" viewBox="0 0 24 24"><path d="M12 3 3 8l9 5 9-5-9-5Z"/><path d="m3 13 9 5 9-5"/></svg>'
  };
  function render(){
    var q=state.q, terms=norm(q).trim().split(/\s+/).filter(Boolean), all=state.results;
    var counts={All:all.length}; TYPES.forEach(function(t){ counts[t]=all.filter(function(r){ return r.type===t; }).length; });
    if(state.filter!=='All' && !counts[state.filter]) state.filter='All';
    srTitle.innerHTML = q ? 'Results for “'+esc(q)+'”' : 'Search DataHub';
    srSub.textContent = q ? (all.length ? all.length+' result'+(all.length>1?'s':'')+' across dashboards, insights and themes' : 'No matches found') : 'Search across every dashboard, insight and theme page.';
    srInput.value=q; navInput.value=q;
    srFilters.innerHTML = all.length ? ['All'].concat(TYPES).filter(function(t){ return t==='All'||counts[t]; }).map(function(t){
      return '<button type="button" class="sr-chip'+(state.filter===t?' active':'')+'" data-f="'+t+'" aria-pressed="'+(state.filter===t)+'">'+t+' <span>'+counts[t]+'</span></button>';
    }).join('') : '';
    if(!q){ srList.innerHTML=''; return; }
    if(!all.length){
      srList.innerHTML='<div class="sr-empty"><h3>Nothing matched “'+esc(q)+'”</h3><p>Check the spelling, use fewer words, or try one of these:</p><div class="sr-suggest">'+
        SUGGEST.map(function(s){ return '<button type="button" class="pill" data-q="'+esc(s)+'">'+esc(s)+'</button>'; }).join('')+'</div></div>';
      return;
    }
    var list=all.filter(function(r){ return state.filter==='All'||r.type===state.filter; }), html='', last='';
    list.forEach(function(r){
      var i=all.indexOf(r);
      if(state.filter==='All' && r.type!==last){ html+='<h2 class="sr-group">'+r.type+'</h2>'; last=r.type; }
      var thumb = r.type==='Insights' && r.thumb ? r.thumb : '<span class="sr-ico">'+(ICON[r.type]||'')+'</span>';
      var action = r.type==='Insights' ? 'Read insight' : r.type==='Dashboards' ? 'View dashboard card' : 'Open theme page';
      html+='<article class="sr-item"><button type="button" class="sr-open" data-i="'+i+'"><span class="sr-thumb'+(r.type!=='Insights'?' sr-thumb-ico':'')+'">'+thumb+'</span>'+
        '<span class="sr-body"><span class="sr-kicker"><b>'+r.type.replace(/s$/,'')+'</b>'+(r.meta?' · '+esc(r.meta):'')+(r.source?' · '+esc(r.source):'')+'</span>'+
        '<span class="sr-title">'+hl(r.title,terms)+'</span><span class="sr-snip">'+hl(snippet(r,terms),terms)+'</span>'+
        '<span class="sr-more">'+action+' &rarr;</span></span></button>'+
        (r.href?'<a class="sr-ext" href="'+esc(r.href)+'" target="_blank" rel="noopener">Open full dashboard <svg class="icon" viewBox="0 0 24 24"><path d="M7 17 17 7M8 7h9v9"/></svg></a>':'')+'</article>';
    });
    srList.innerHTML=html;
  }
  function activeViewKey(){
    var v=document.querySelector('.view.active'); if(!v||v.id==='view-search') return state.prev;
    return v.id.replace('view-','');
  }
  function showResults(q, push){
    q=(q||'').trim();
    if(document.querySelector('.view.active') && document.querySelector('.view.active').id!=='view-search') state.prev=activeViewKey();
    state.q=q; state.filter='All'; state.results=run(q);
    if(typeof restoreThemeMoves==='function') restoreThemeMoves();
    document.querySelectorAll('.view').forEach(function(v){ v.classList.remove('active'); });
    view.classList.add('active'); window.scrollTo({top:0,behavior:'instant'});
    render();
    var h='#search='+encodeURIComponent(q);
    if(push && location.hash!==h) history.pushState({dhSearch:q},'',h);
    var nav=document.querySelector('.sitebar'); if(nav) nav.classList.remove('nav-open');
  }
  function leaveSearchHash(){ if(location.hash.indexOf('#search=')===0) history.pushState(null,'',location.pathname+location.search); }
  // keep the URL clean when the visitor navigates elsewhere
  if(typeof showView==='function'){ var _sv=showView; showView=function(){ leaveSearchHash(); return _sv.apply(this,arguments); }; }
  if(typeof showThemeView==='function'){ var _stv=showThemeView; showThemeView=function(){ leaveSearchHash(); return _stv.apply(this,arguments); }; }

  function openResult(r){
    if(r.type==='Insights'){
      var c=document.querySelector('.insight-card.listing[data-modal="'+r.key+'"]'); if(c) c.click();
    } else if(r.type==='Dashboards'){
      showView('dashboards');
      var t=document.querySelector('.db-tab[data-tab="'+r.tab+'"]'); if(t) t.click();
      setTimeout(function(){
        var card=document.getElementById(r.id); if(!card) return;
        if(!card.classList.contains('open')){ var h=card.querySelector('.dbcard-head'); if(h) h.click(); }
        window.scrollTo({top:card.getBoundingClientRect().top+window.scrollY-90,behavior:'smooth'});
        card.classList.remove('ds-flash'); void card.offsetWidth; card.classList.add('ds-flash');
      },120);
    } else if(r.type==='Themes'){ showThemeView(r.theme); }
  }
  navForm.addEventListener('submit', function(e){ e.preventDefault(); var q=navInput.value.trim(); if(!q){ navInput.focus(); return; } navInput.blur(); showResults(q,true); });
  srForm.addEventListener('submit', function(e){ e.preventDefault(); showResults(srInput.value,true); });
  srFilters.addEventListener('click', function(e){ var b=e.target.closest('.sr-chip'); if(!b) return; state.filter=b.getAttribute('data-f'); render(); });
  srList.addEventListener('click', function(e){
    var s=e.target.closest('[data-q]'); if(s){ showResults(s.getAttribute('data-q'),true); return; }
    var b=e.target.closest('.sr-open'); if(b) openResult(state.results[+b.getAttribute('data-i')]);
  });
  window.addEventListener('popstate', function(){
    if(location.hash.indexOf('#search=')===0){ showResults(decodeURIComponent(location.hash.slice(8)),false); }
    else if(view.classList.contains('active')){
      var p=state.prev||'home';
      if(/^theme-/.test(p)) showThemeView(p.replace('theme-','')); else showView(p);
    }
  });
  document.addEventListener('keydown', function(e){
    if(e.key==='/' && !/input|textarea|select/i.test((document.activeElement||{}).tagName||'')){ e.preventDefault(); navInput.focus(); navInput.select(); }
  });
  if(location.hash.indexOf('#search=')===0){ showResults(decodeURIComponent(location.hash.slice(8)),false); }
})();

/* ---- "Explore the data" links at the end of insight popups ---- */
(function(){
  var INS; try{ INS=INSIGHTS; }catch(e){ return; }
  var L={
    plfs:['PLFS Workforce Dashboard','https://theudaitifoundation-datahub.github.io/PLFS/'],
    story:["Where are India's Working Women?",'https://www.udaiti.org/india-women-work'],
    asuse:['ASUSE 2025 – A Snapshot of Female-headed Establishments in India','https://www.udaiti.org/ASUSE_Data_Pack_13.11.html'],
    spi:['State Startup Policy Index','https://theudaitifoundation-datahub.github.io/Startup_Policy/'],
    epfo:['EPFO Tracker','https://epfodata.z29.web.core.windows.net/'],
    cgg:["Women's Formal Employment Tracker",'https://cggdashboarddata.z29.web.core.windows.net/']
  };
  var MAP={
    'insight-1':['plfs','story'],'insight-2':['plfs','story'],'insight-3':['plfs','story'],
    'insight-no-contract':['plfs','story'],'insight-secure-jobs-gap':['plfs','story'],
    'insight-17':['asuse'],'insight-market-access':['spi'],'insight-epf-subscribers':['epfo'],
    'insight-14':['cgg'],'insight-15':['cgg'],'insight-kmp-company-size':['cgg'],'insight-board-kmp':['cgg'],
    'insight-pay-gap':['cgg'],'insight-it-banks':['cgg']
  };
  Object.keys(MAP).forEach(function(k){
    var d=INS[k]; if(!d||!d.body||d.__dhLinks) return; d.__dhLinks=true;
    d.body=d.body.concat(['<span class="dh-explore"><b>Explore the data:</b> '+MAP[k].map(function(x){
      return '<a href="'+L[x][1]+'" target="_blank" rel="noopener">'+L[x][0]+' &#8599;</a>'; }).join(' · ')+'</span>']);
  });
})();

